from html import escape


def page(title: str, body: str) -> str:
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} · Face Photo Finder</title><style>
:root{{--bg:#f4f6f8;--card:#fff;--ink:#172033;--muted:#667085;--line:#e3e8ef;--accent:#2457d6;--ok:#137a42}}*{{box-sizing:border-box}}body{{margin:0;font-family:Inter,ui-sans-serif,system-ui,-apple-system,sans-serif;background:var(--bg);color:var(--ink)}}header{{background:#111827;color:#fff;padding:16px 24px}}nav{{max-width:1180px;margin:auto;display:flex;align-items:center;justify-content:space-between;gap:16px}}nav a{{color:#fff;text-decoration:none;margin-left:18px}}main{{max-width:1180px;margin:34px auto;padding:0 22px}}.card{{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:24px;box-shadow:0 8px 28px rgba(16,24,40,.05);margin-bottom:18px}}.grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px}}.stat{{font-size:30px;font-weight:750}}.muted{{color:var(--muted)}}.row{{display:flex;gap:12px;align-items:center;flex-wrap:wrap}}input,select{{padding:11px 12px;border:1px solid #cfd6df;border-radius:9px;min-width:220px;background:white}}button,.button{{background:var(--accent);color:white;border:0;border-radius:9px;padding:11px 15px;font-weight:650;cursor:pointer;text-decoration:none;display:inline-block}}.secondary{{background:#344054}}table{{width:100%;border-collapse:collapse}}th,td{{text-align:left;padding:12px;border-bottom:1px solid var(--line);vertical-align:top}}.pill{{display:inline-block;padding:5px 9px;border-radius:999px;background:#eef3ff;color:#244aa5;font-size:12px}}h1,h2{{margin-top:0}}code{{font-size:12px}}@media(max-width:700px){{table{{display:block;overflow:auto}}}}
</style></head><body><header><nav><strong>Face Photo Finder</strong><div><a href="/">Home</a><a href="/ui/projects">Projects</a><a href="/ui/accounts">Storage Accounts</a></div></nav></header><main>{body}</main></body></html>'''
